export function Pulse({
  enabled = {{enabled}},
  duration = {{duration}},
  scaleAmount = {{scaleAmount}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ position: "relative", width: "100%", maxWidth: 320, padding: 26, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa", textAlign: "center" }}>
      <span className={enabled ? "ring on" : "ring"} style={{ position: "absolute", top: 26, left: "calc(50% - 12px)", width: 24, height: 24, borderRadius: 999, border: `2px solid ${accent}`, opacity: 0, "--pulse-scale": `${scaleAmount}%` }} />
      <span style={{ position: "relative", display: "inline-block", width: 24, height: 24, borderRadius: 999, background: accent }} />
      <p style={{ margin: "12px 0 0" }}>{enabled ? "Pulsing" : "Static"} &middot; {duration}ms &middot; draws attention to a live indicator</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .ring.on { animation: mot-pul-ring ${duration}ms ease-out infinite; }
          @keyframes mot-pul-ring { 0% { transform: scale(1); opacity: .6; } 100% { transform: scale(calc(1 + var(--pulse-scale) / 100)); opacity: 0; } }
        }
      `}</style>
    </div>
  );
}
